miniLab.verifyScript:
param(
    [string]$CapstoneDir = $env:CAPSTONE_DIR
)
$ErrorActionPreference = "Stop"
$fails = 0
$passes = 0
if (-not $CapstoneDir) { $CapstoneDir = (Get-Location).Path }
if (-not (Test-Path (Join-Path $CapstoneDir "src")) -and (Test-Path (Join-Path $CapstoneDir "capstone-ext"))) {
    $CapstoneDir = Join-Path $CapstoneDir "capstone-ext"
}
function Check {
    param([string]$Name, [bool]$Ok, [string]$Detail)
    if ($Ok) { Write-Host "[PASS]  $Name"; $script:passes++ }
    else { Write-Host "[FAIL]  $Name - $Detail"; $script:fails++ }
}
$hasManifest = (Test-Path (Join-Path $CapstoneDir "plugin.json")) -or (Test-Path (Join-Path $CapstoneDir "Cargo.toml")) -or (Test-Path (Join-Path $CapstoneDir "config.example.yaml"))
Check "manifest present (plugin.json / Cargo.toml / config.example.yaml)" $hasManifest "capstone root: $CapstoneDir"
$hasSrc = (Test-Path (Join-Path $CapstoneDir "src")) -or (Test-Path (Join-Path $CapstoneDir "commands")) -or (Test-Path (Join-Path $CapstoneDir "skills"))
Check "implementation dir present (src/ or commands/ or skills/)" $hasSrc "create the implementation"
$testFiles = @()
if (Test-Path (Join-Path $CapstoneDir "tests")) { $testFiles = Get-ChildItem (Join-Path $CapstoneDir "tests") -Filter *.rs }
Check "tests/ has at least one test file" ($testFiles.Count -ge 1) "add tests/*.rs"
Check "README.md exists" (Test-Path (Join-Path $CapstoneDir "README.md")) "write install + usage docs"
Check "docs/design.md exists" (Test-Path (Join-Path $CapstoneDir "docs\design.md")) "write the design + security doc"
$qa = Join-Path $CapstoneDir "qa-report.txt"
$qaOk = $false
if (Test-Path $qa) {
    $qaText = Get-Content $qa -Raw
    $qaOk = ($qaText -match "test result:") -and ($qaText -match "CLIPPY-RUN-DONE|GATES-RUN-DONE")
}
Check "qa-report.txt shows cargo test result + clippy/gates markers" $qaOk "run fmt/test/clippy and record the output"
Check "demo.md live-session transcript exists" (Test-Path (Join-Path $CapstoneDir "demo.md")) "record one live session using your extension"
Write-Host ""
Write-Host "CAPSTONE scan complete: $passes/$($passes + $fails) structure checks"
if ($fails -eq 0) {
    Write-Host "STRUCTURE OK - every capstone artifact present"
    Write-Host "VERIFY PASSED $passes/$($passes + $fails)"
    exit 0
} else {
    Write-Host "VERIFY FAILED - $fails of $($passes + $fails) checks failed"
    exit 1
}
